, \"Actual Sku\", remarks, qty, \"UPDATED BY\", \"Physical sku\", \"Actual vs physical\" from snitch_db.maplemonk.gs_cycle2error where location is not null ; create or replace table snitch_db.maplemonk.inward_inventory as select sl_no, ageing, erp_po, sku_no, mail_id, po_number, qc_status, grn_number, inward_sla, TRY_TO_NUMBER(REGEXP_REPLACE(online_qty, \'[^0-9.-]\', \'\')) AS TOTAL_ORDERED_QTY, style_type, po_quantity as po_quantity, remarks_qty, strike_sent, vendor_name, vendor_type, try_to_date(planned_date,\'YYYY-MM-DD\') as planned_date, sku_received, ratio_done_by, invoice_number, invoice_status, putaway_number, vendor_remarks, expected_timing, try_to_date(po_request_date,\'YYYY-MM-DD\') as po_request_date, putaway_done_by, breached_remarks, grn_created_date, po_number_created, po_request_done_by, delivery_status_type, try_to_date(ratio_completed_date,\'YYYY-MM-DD\') as ratio_completed_date, try_to_date(actual_delivered_date,\'YYYY-MM-DD\') as actual_delivered_date, \"Vehicle ariival staus\", vehicle_received_time, vehicle_unload_status, vehicle_unloaded_time, try_to_date(putaway_completed_date,\'YYYY-MM-DD\') as putaway_completed_date, try_to_date(considered_delivered_date,\'YYYY-MM-DD\') as considered_delivered_date, \"Vehicle recived to unload\", TRY_TO_NUMBER(REGEXP_REPLACE(quantity_received_as_per_invoice, \'[^0-9.-]\', \'\')) AS quantity_received_as_per_invoice, from snitch_db.maplemonk.gs_inventory_in_sheet where sku_no is not null order by considered_delivered_date desc ;",
